sys_script_fix.script:
// This Fix job has a 3 step process.
fixNameUniquenessAndMandatory();
if(reparentJMSTable()){
    dropRedundantData();
    reconcileConnectionAlias();
} else {
		gs.warn('Reparenting orch_jms_ds table from sys_metadata to sys_connection failed');
}


// Fix the mandatory and uniqueness check for name on child table

function fixNameUniquenessAndMandatory() {

	var agg = new GlideAggregate('orch_jms_ds');
	agg.addAggregate('count');
	agg.groupBy('name');
	agg.query();

	while (agg.next()) {

		var name = agg.name;
		var count = agg.getAggregate('count');
		gs.info('Name in JMS Connection Table:' + (name ? name:"null") + ' Number of Records found: ' + count );

		if(count > 1 || !name) {

			var suffix =0;
			var gr = new GlideRecord('orch_jms_ds');
			gr.addQuery('name',name);
			gr.query();
			while(gr.next()) {
				if(name) {
					gr.name = name + suffix;
				} else {
					gr.name = 'JMS'+ suffix;
				}
				gr.update();
				gs.info('Updated Name:' + gr.name + ' for Sys id:' + gr.getUniqueValue());
				suffix++;
			}
		}
	}

}
// Source or Child table is all good with required constraints.
function reparentJMSTable() {
	// Reparent after querying so that it doesn't impact the query
	return SNC.CMDBUtil.reParentTable('orch_jms_ds', 'sys_metadata', 'sys_connection');
}

function dropRedundantData() {	
	gs.dropColumn('orch_jms_ds', 'sys_scope');
	gs.dropColumn('orch_jms_ds', 'sys_policy');
	gs.dropColumn('orch_jms_ds', 'sys_package');
}

function reconcileConnectionAlias() {
	var jmsDS = new GlideRecord('orch_jms_ds');
	jmsDS.query();
	while(jmsDS.next()) {		
		// Create Alisa records based on the new name field
		var jmsAlias = new GlideRecord('sys_alias');
		jmsAlias.initialize();
		jmsAlias.name = jmsDS.name;
		jmsAlias.type = 'connection';
		jmsAlias.connection_type = 'orch_jms_ds';
		jmsAlias.insert();

		jmsDS.active = true;
		jmsDS.connection_alias = jmsAlias.getUniqueValue();
		jmsDS.update();
	}
}
